55	const PROCESSING_FEE = 5;
56	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
57	
58	const BASE_PREMIUMS: Record<string, number> = {
59	  sword: 100,
60	  amulet: 60,
61	  staff: 80,
62	  potion: 40,
63	  rune: 25,
64	  moonstone: 25,
65	};
66	
67	const ALIKE_ITEMS_PER_BLOCK = 3;
68	const BLOCK_BASE_PREMIUM = 60;
69	
70	const basePremiumForAlikeItems = (type: string, count: number): number => {
71	  if (count === ALIKE_ITEMS_PER_BLOCK) return BLOCK_BASE_PREMIUM;
72	  return count * BASE_PREMIUMS[type];
73	};
74	
75	const countByType = (items: Item[]): Map<string, number> =>
76	  items.reduce(
77	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
78	    new Map<string, number>(),
79	  );
80	
81	const policyBasePremium = (items: Item[]): number =>
82	  [...countByType(items)].reduce(
83	    (total, [type, count]) => total + basePremiumForAlikeItems(type, count),
84	    0,
85	  );
86	
87	const quotePremium = (items: Item[]): number => {
88	  const policyBase = policyBasePremium(items);
89	  const firstInsuranceSurcharge = policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
90	  return Math.ceil(policyBase + firstInsuranceSurcharge + PROCESSING_FEE);
91	};
92	
93	const runStep = (step: Step): StepResult => ({
94	  premium: quotePremium((step as QuoteStep).items),
95	});
96	
97	export const runScenario = (scenario: Scenario): ScenarioResult => ({
98	  results: scenario.steps.map(runStep),
99	});
